    "passagePlain": "マンガが描く世界は、人物であれ世界であれ、現実の世界のイメージを基本的には基礎としながらも、極端な誇張や省略をしたり、現実にはあり得ない世界を自由に構築したりすることが許される。このような制約の少なさの点では、テキストであらゆるものを表現しうる文学の世界とも共通する点が多い。文学の世界では実際の視覚情報を直接扱わないことでテキストで世界を描くことでこの自由度が与えられたが、マンガの世界ではイラスト（注１）的視覚表現によって実写的な視覚情報をいくらでも省略、誇張、変形ができることから、実写中心の視覚情報の制約を脱することに見事に成功している。\n\n(注1) イラスト：「イラストレーション」の略。書物や広告に用いられる説明や装飾のための挿絵・図解や写真。",
