    "passageTrans": "만화가 그리는 세계는 인물이든 세계이든 현실 세계의 이미지를 기본적으로는 기초로 하면서도, 극단적인 과장이나 생략을 하거나 현실에는 있을 수 없는 세계를 자유롭게 구축하는 것이 허용된다. 이러한 제약의 적음이라는 점에서는 텍스트로 모든 것을 표현할 수 있는 문학의 세계와도 공통점이 많다. 문학의 세계에서는 실제 시각 정보를 직접 다루지 않고 텍스트로 세계를 묘사함으로써 이 자유도가 주어졌지만, 만화의 세계에서는 일러스트(주1)적 시각 표현을 통해 실사적인 시각 정보를 얼마든지 생략, 과장, 변형할 수 있다는 점에서 실사 중심의 시각 정보 제약을 벗어나는 데 훌륭하게 성공하고 있다.\n\n(주1) 일러스트: '일러스트레이션'의 줄임말. 책이나 광고에 사용되는 설명과 장식을 위한 삽화·도해나 사진.",
