    "passagePlain": "[文章A]\n裁判員制度の導入は、日本の司法を国民にとって身近なものへと変革する画期的な試みである。従来の裁判は、専門家による難解な法律用語と前例踏襲の硬直した論理に支配され、一般市民の常識的感覚からかけ離れていた。裁判員制度によって市民が直接審理に参加することで、社会の健全な良識が判決に反映され、司法に対する国民の信頼を高めることができる。また、国民一人ひとりが法や正義、さらには社会問題について当事者意識を持って深く考える契機ともなる。制度の初期には多少の混乱や負担があっても、民主主義の成熟という観点から積極的に支持されるべきである。\n\n[文章B]\n裁判員制度には理念としての意義はあるものの、現実の運用においては多くの深刻な問題点が潜んでいる。重大な刑事事件において、専門的訓練を受けていない一般市民が人の生死や長期の自由刑を判断することの心理的負担は計り知れない。裁判後に過度のストレスやトラウマを訴える裁判員も少なくない。さらに、感情的な世論やマスコミの過熱報道に左右され、論理的な証拠裁判主義が揺らぐ危険性も否定できない。本来プロの裁判官が責任を持って果たすべき重責を、十分な保護やサポートのないまま一般市民に転嫁することは、司法の責任放棄と言われても仕方がないのではないか。",
    "passageRuby": "[文章A]<br>裁判員制度(さいばんいんせいど)の導入(どうにゅう)は、日本(にほん)の司法(しほう)を国民(こくみん)にとって身近(みぢか)なものへと変革(へんかく)する画期的(かっきてき)な試(こころ)みである。従来(じゅうらい)の裁判(さいばん)は、専門家(せんもんか)による難解(なんかい)な法律用語(ほうりつようご)と前例踏襲(ぜんれいとうしゅう)の硬直(こうちょく)した論理(ろんり)に支配(しはい)され、一般市民(いっぱんしみん)の常識的感覚(じょうしきてきかんかく)からかけ離(はな)れていた。裁判員制度(さいばんいんせいど)によって市民(しみん)が直接(ちょくせつ)審理(しんり)に参加(さんか)することで、社会(しゃかい)の健全(けんぜん)な良識(りょうしき)が判決(はんけつ)に反映(はんえい)され、司法(しほう)に対(たい)する国民(こくみん)の信頼(しんらい)を高(たか)めることができる。また、国民(こくみん)一人(ひとり)ひとりが法(ほう)や正義(せいぎ)、さらには社会問題(しゃかいもんだい)について当事者意識(とうじしゃいしき)を持(も)って深(ふか)く考(かんが)える契機(けいき)ともなる。制度(せいど)の初期(しょき)には多少(たしょう)の混乱(こんらん)や負担(ふたん)があっても、民主主義(みんしゅしゅぎ)の成熟(せいじゅく)という観点(かんてん)から積極的(せっきょくてき)に支持(しじ)されるべきである。<br><br>[文章B]<br>裁判員制度(さいばんいんせいど)には理念(りねん)としての意義(いぎ)はあるものの、現実(げんじつ)の運用(うんよう)においては多(おお)くの深刻(しんこく)な問題点(もんだいてん)が潜(ひそ)んでいる。重大(じゅうだい)な刑事事件(けいじじけん)において、専門的訓練(せんもんてきくんれん)を受(う)けていない一般市民(いっぱんしみん)が人(ひと)の生死(せいし)や長期(ちょうき)の自由刑(じゆうけい)を判断(はんだん)することの心理的負担(しんりてきふたん)は計(はか)り知(し)れない。裁判後(さいばんご)に過度(かど)のストレスやトラウマを訴(うった)える裁判員(さいばんいん)も少(すく)なくない。さらに、感情的(かんじょうてき)な世論(せろん)やマスコミの過熱報道(かねつほうどう)に左右(さゆう)され、論理的(ろんりてき)な証拠裁判主義(しょうこさいばんしゅぎ)が揺(ゆ)らぐ危険性(きけんせい)も否定(ひてい)できない。本来(ほんらい)プロの裁判官(さいばんかん)が責任(せきにん)を持(も)って果(は)たすべき重責(じゅうせき)を、十分(じゅうぶん)な保護(ほご)やサポートのないまま一般市民(いっぱんしみん)に転嫁(てんか)することは、司法(しほう)の責任放棄(せきにんほうき)と言(い)われても仕方(しかた)がないのではないか。",
    "passageTrans": "[문장 A]\n재판원 제도의 도입은 일본의 사법을 국민에게 친숙한 것으로 변혁시키는 획기적인 시도이다. 종래의 재판은 전문가에 의한 난해한 법률 용어와 전례 답습의 경직된 논리에 지배되어 일반 시민의 상식적 감각과 동떨어져 있었다. 재판원 제도로 인해 시민이 직접 심리에 참여함으로써 사회의 건전한 양식이 판결에 반영되고, 사법에 대한 국민의 신뢰를 높일 수 있다. 또한 국민 개개인이 법과 정의, 나아가 사회문제에 대해 당사자 의식을 가지고 깊이 생각하는 계기가 되기도 한다. 제도의 초기에는 다소의 혼란이나 부담이 있더라도 민주주의의 성숙이라는 관점에서 적극적으로 지지받아야 한다.\n\n[문장 B]\n재판원 제도에는 이념으로서의 의의는 있을지언정, 현실의 운용에 있어서는 많은 심각한 문제점이 도사리고 있다. 중대한 형사사건에서 전문적 훈련을 받지 않은 일반 시민이 사람의 생사나 장기 자유형을 판단해야 하는 심리적 부담은 헤아릴 수 없다. 재판 후에 과도한 스트레스나 트라우마를 호소하는 재판원도 적지 않다. 게다가 감정적인 여론이나 언론 매체의 과열 보도에 좌우되어 논리적인 증거재판주의가 흔들릴 위험성도 부정할 수 없다. 본래 프로 재판관이 책임을 지고 완수해야 할 중책을 충분한 보호나 지원 없이 일반 시민에게 전가하는 것은 사법의 책임 방기라고 불려도 어쩔 수 없는 것이 아닐까.",
