    "estimatedMinutes": 5,
    "passagePlain": "右のページは、東洋大学が主催する『久保田弘信講演会』の案内である。留学生である金さんは、今回の講演会に参加しようと思っている。下の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━\n【東洋大学 / 第52回11月祭】\n\n■ 学校名：東洋大学東キャンパス\n■ 学園祭名：第52回 11月祭\n■ 開催日：11月17日(土) 〜 20日(火)\n■ 住所：堺市泉が丘本町\n■ HomePage：http://harayamadai.la/\n\n【講演会詳細】\n日時：11月18日(日)\n・第一回講演 13:00〜14:30\n  「アフガン 伝えきれなかった真実」\n・第二回講演 15:30〜17:00\n  「イラク 伝えきれなかった真実」\n※受付開始は、各講演開始の45分前になります。\n会場：東洋大学東キャンパス東32教室\n（電車「泉が丘駅前」より徒歩10分）\n\n料金：一講演につき\n・社会人：当日 550円 / 前売り 500円\n・学生：当日 400円 / 前売り 350円（中学生以下無料）\n講師：フォトジャーナリスト、久保田弘信氏\nホームページ：http://kubotahironobulive.blog114.fc2.com/\n\n予約・問合せ：久保田弘信講演会運営スタッフ khk-nf@hotmail.co.jp\n\n※ご予約の際は、①お名前 ②メールアドレス ③社会人／学生 ④ご希望の講演会（アフガン／イラク）を明記の上、上記アドレスまでご連絡くださいますようお願いいたします。また、今回は特別に懇親会を予定しております。詳細をご希望の方は、ご予約の際にあわせてお問い合わせ下さいませ。\n━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "passageRuby": "右(みぎ)のページは、東洋大学(とうようだいがく)が主催(しゅさい)する『久保田弘信講演会(くぼたひろのぶこうえんかい)』の案内(あんない)である。留学生(りゅうがくせい)である金(きむ)さんは、今回(こんかい)の講演会(こうえんかい)に参加(さんか)しようと思(おも)っている。下(した)の問(と)いに対(たい)する答(こた)えとして最(もっと)もよいものを、1・2・3・4から一(ひと)つ選(えら)びなさい。\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━\n【東洋大学(とうようだいがく) / 第52回(だいごじゅうにかい)11月祭(じゅういちがつさい)】\n\n■ 学校名(がっこうめい)：東洋大学東(とうようだいがくひがし)キャンパス\n■ 学園祭名(がくえんさいめい)：第52回(だいごじゅうにかい) 11月祭(じゅういちがつさい)\n■ 開催日(かいさいび)：11月(がつ)17日(にち)(土(ど)) 〜 20日(にち)(火(か))\n■ 住所(じゅうしょ)：堺市泉(さかいしいずみ)が丘本町(おかほんちょう)\n■ HomePage：http://harayamadai.la/\n\n【講演会詳細(こうえんかいしょうさい)】\n日時(にちじ)：11月(がつ)18日(にち)(日(にち))\n・第一回講演(だいいっかいこうえん) 13:00〜14:30\n  「アフガン 伝(つた)えきれなかった真実(しんじつ)」\n・第二回講演(だいにかいこうえん) 15:30〜17:00\n  「イラク 伝(つた)えきれなかった真実(しんじつ)」\n※<u>受付開始(うけつけかいし)は、各講演開始(かくこうえんかいし)の45分前(よんじゅうごふんまえ)になります</u>。\n会場(かいじょう)：東洋大学東(とうようだいがくひがし)キャンパス東(ひがし)32教室(きょうしつ)\n（電車(でんしゃ)「泉(いずみ)が丘駅前(おかえきまえ)」より徒歩(とほ)10分(ぷん)）\n\n料金(りょうきん)：一講演(いっこうえん)につき\n・社会人(しゃかいじん)：当日(とうじつ) 550円(えん) / 前売(まえう)り 500円(えん)\n・<u>学生(がくせい)：当日(とうじつ) 400円(えん) / 前売(まえう)り 350円(えん)</u>（中学生以下無料(ちゅうがくせいいかむりょう)）\n講師(こうし)：フォトジャーナリスト、久保田弘信氏(くぼたひろのぶし)\nホームページ：http://kubotahironobulive.blog114.fc2.com/\n\n予約(よやく)・問合(といあわ)せ：久保田弘信講演会運営(くぼたひろのぶこうえんかいうんえい)スタッフ khk-nf@hotmail.co.jp\n\n※ご予約(よやく)の際(さい)は、①お名前(なまえ) ②メールアドレス ③社会人(しゃかいじん)／学生(がくせい) ④ご希望(きぼう)の講演会(こうえんかい)（アフガン／イラク）を明記(めいき)の上(うえ)、上記(じょうき)アドレスまでご連絡(れんらく)くださいますようお願(ねが)いいたします。<u>また、今回(こんかい)は特別(とくべつ)に懇親会(こんしんかい)を予定(よてい)しております。詳細(しょうさい)をご希望(きぼう)の方(かた)は、ご予約(よやく)の際(さい)にあわせてお問(と)い合(あ)わせ下(くだ)さいませ</u>。\n━━━━━━━━━━━━━━━━━━━━━━━━━━",
    "passageTrans": "오른쪽 페이지는 도요대학이 주최하는 『구보타 히로노부 강연회』의 안내문이다. 유학생인 김 씨는 이번 강연회에 참가하고자 한다. 아래 질문에 가장 알맞은 답을 1, 2, 3, 4에서 하나 고르시오.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━\n【도요대학 / 제52회 11월 축제】\n\n■ 학교명: 도요대학 동캠퍼스\n■ 축제명: 제52회 11월 축제\n■ 개최일: 11월 17일(토) ~ 20일(화)\n■ 주소: 사카이시 이즈미가오카혼초\n■ 홈페이지: http://harayamadai.la/\n\n【강연회 상세】\n일시: 11월 18일(일)\n· 제1회 강연 13:00~14:30 「아프간 다 전하지 못한 진실」\n· 제2회 강연 15:30~17:00 「이라크 다 전하지 못한 진실」\n※ 접수 시작은 각 강연 시작 45분 전부터입니다.\n장소: 도요대학 동캠퍼스 동32 강의실 ('이즈미가오카역 앞' 도보 10분)\n\n요금: 강연 1회당\n· 일반: 당일 550엔 / 예매 500엔\n· 학생: 당일 400엔 / 예매 350엔 (중학생 이하 무료)\n강사: 포토저널리스트 구보타 히로노부 씨\n\n예약 및 문의: 구보타 히로노부 강연회 운영스태프 khk-nf@hotmail.co.jp\n※ 예약 시 ①성함 ②메일 주소 ③일반/학생 구분 ④희망 강연(아프간/이라크)을 명기하여 상기 주소로 연락 바랍니다. 아울러 이번에는 특별히 간담회를 예정하고 있습니다. 상세 내용을 희망하시는 분은 예약 시 함께 문의해 주시기 바랍니다.\n━━━━━━━━━━━━━━━━━━━━━━━━━━",
