    "passagePlain": "日本の俳句が、伝統的に、「季感」を主軸として成立してきたことは、[11]周知の事実である。五・七・五という極めて短い定型詩の中に季節の言葉（季語）を盛り込むことによって、自然界の広大無辺な時間の流れと、人間の微細な感情とを瞬時に結びつけるのである。[12]、近年の映像芸術、とりわけ映画表現においても、この「季感」という要素が極めて重要な機能を果たしていることが指摘されている。スクリーンの上に風が吹き、雨が降り、あるいは木々の葉が色づく瞬間、観客は視覚情報以上の季節の情感を皮膚感覚として[13]。\n\n映画のカメラは、外界の事物を客観的に記録する機械である。しかし、監督や撮影者が季節の光や影に鋭敏な目を向けたとき、その映像は単なる風景の記録を超えて、登場人物の内面心理や運命の予感を象徴する詩的空間へと変貌する。そこには、俳句の作者が自然の風物に[14]を投影したのと全く同じ精神の働きが見出されるのである。\n\nかかる考え方をするならば、いずれの芸術であれ、この切々たる存在への哀感なくして芸術そのものが[15]、どうして俳句だけにとどまりえようか。日本の伝統的な自然観と近代の映像表現は、まさにこの「季感」という深い根底において響き合っているのである。",
    "passageRuby": "日本(にほん)の俳句(はいく)が、伝統的(でんとうてき)に、「季感(きかん)」を主軸(しゅじく)として成立(せいりつ)してきたことは、[11]周知(しゅうち)の事実(じじつ)である。五(ご)・七(しち)・五(ご)という極(きわ)めて短(みじか)い定型詩(ていけいし)の中(なか)に季節(きせつ)の言葉(ことば)（季語(きご)）を盛(も)り込(こ)むことによって、自然界(しぜんかい)の広大無辺(こうだいむへん)な時間(じかん)の流(なが)れと、人間(にんげん)の微細(びさい)な感情(かんじょう)とを瞬時(しゅんじ)に結(むす)びつけるのである。[12]、近年(きんねん)の映像芸術(えいぞうげいじゅつ)、とりわけ映画表現(えいがひょうげん)においても、この「季感(きかん)」という要素(ようそ)が極(きわ)めて重要(じゅうよう)な機能(きのう)を果(は)たしていることが指摘(してき)されている。スクリーン(すくりーん)の上(うえ)に風(かぜ)が吹(ふ)き、雨(あめ)が降(ふ)り、あるいは木々(きぎ)の葉(は)が色(いろ)づく瞬間(しゅんかん)、観客(かんきゃく)は視覚情報(しかくじょうほう)以上(いじょう)の季節(きせつ)の情感(じょうかん)を皮膚感覚(ひふかんかく)として[13]。<br><br>映画(えいが)のカメラ(かめら)は、外界(がいかい)の事物(じぶつ)を客観的(きゃっかんてき)に記録(きろく)する機械(きかい)である。しかし、監督(かんとく)や撮影者(さつえいしゃ)が季節(きせつ)の光(ひかり)や影(かげ)に鋭敏(えいびん)な目(め)を向(む)けたとき、その映像(えいぞう)は単(たん)なる風景(ふうけい)の記録(きろく)を超(こ)えて、登場人物(とうじょうじんぶつ)の内面心理(ないめんしんり)や運命(うんめい)の予感(よかん)を象徴(しょうちょう)する詩的空間(してきくうかん)へと変貌(へんぼう)する。そこには、俳句(はいく)の作者(さくしゃ)が自然(しぜん)の風物(ふうぶつ)に[14]を投影(とうえい)したのと全(まった)く同(おな)じ精神(せいしん)の働(はたら)きが見出(みいだ)されるのである。<br><br>かかる考(かんが)え方(かた)をするならば、いずれの芸術(げいじゅつ)であれ、この切々(せつせつ)たる存在(そんざい)への哀感(あいかん)なくして芸術(げいじゅつ)そのものが[15]、どうして俳句(はいく)だけにとどまりえようか。日本(にほん)の伝統的(でんとうてき)な自然観(しぜんかん)と近代(きんだい)の映像表現(えいぞうひょうげん)は、まさにこの「季感(きかん)」という深(ふか)い根底(こんてい)において響(ひび)き合(あ)っているのである。",
    "passageTrans": "일본의 하이쿠가 전통적으로 '계절감(季感)'을 주축으로 성립되어 온 것은 [11: 널리 간주되고 있는] 주지의 사실이다. 5·7·5라는 지극히 짧은 정형시 속에 계절의 단어(계어)를 담음으로써 자연계의 광대무변한 시간의 흐름과 인간의 미세한 감정을 순식간에 연결하는 것이다. [12: 그런데], 최근의 영상 예술, 특히 영화 표현에 있어서도 이 '계절감'이라는 요소가 대단히 중요한 기능을 하고 있다는 점이 지적되고 있다. 스크린 위에 바람이 불고 비가 내리며 혹은 나무 잎사귀들이 물드는 순간 관객은 시각 정보 이상의 계절 정감을 피부 감각으로서 [13: 느끼고 있는 것이다].\n\n영화의 카메라는 바깥 세계의 사물을 객관적으로 기록하는 기계이다. 그러나 감독이나 촬영자가 계절의 빛과 그림자에 예민한 눈을 돌렸을 때 그 영상은 단순한 풍경의 기록을 넘어 등장인물의 내면 심리나 운명의 예감을 상징하는 시적 공간으로 변모한다. 거기에는 하이쿠 작가가 자연 풍물에 [14: 자신(자아)]을 투영했던 것과 완전히 동일한 정신의 작용이 발견되는 것이다.\n\n이러한 생각을 한다면 어떤 예술이든 이 절절한 존재에 대한 애수 없이 예술 그 자체가 [15: 성립될 리 만무하며], 어찌 하이쿠에만 머무를 수 있겠는가. 일본의 전통적 자연관과 근대의 영상 표현은 바로 이 '계절감'이라는 깊은 뿌리에서 서로 울려 퍼지고 있는 것이다.",
