    "wordCount": 710,
    "estimatedMinutes": 6,
    "passagePlain": "この半年ばかりのうちに、私たちの生活におこった変化は、日本のこれまでのいつの歴史にもその例がないほど激しいものです。日本は今、非常な困難と[21]、民主的な平和の国として世界の独立国として登場するための努力をはじめております。これからの私たち日本人は、世界に恥かしくない市民としてどういう風でなければならないでしょうか。新しい躾（しつけ）の問題も、こういう広い、雄大な立場から考えられなければならないであろうと思います。\n\n躾という字をみますと、美しく身をもつことと思えます。美しく身を持した生活態度というのは、どういうことを指していうのでしょう。昔から躾というと、とかく[22]、折り目正しいキチンとしたことを、躾がよいと[23]。しかし、今日の生活は忙しく、変化が激しく、混んだ電車一つに乗るにしても、実際には昔風の躾とちがった事情がおこって来ています。しとやかに男の人のうしろについて、つつましく乗物にのるのが昔の若い女性の躾でした。しかし毎朝毎夕、満員電車に押しこまれ押し出されて通勤する女性たちは、昔の躾を守っていたら電車一つにも乗れません。生活の現実が、昔の形式的な躾の型を押し流してしまいました。\n\n[24]、私たちの心には、やはり美しく立派な生きかたをしたいと思う念願は強くあります。そうだとすれば、新しい躾の根本は、毎日の荒っぽい生活に[25]根深い根拠をもつものでなければならないということが分ります。",
    "passageRuby": "この半年(はんとし)ばかりのうちに、私(わたし)たちの生活(せいかつ)におこった変化(へんか)は、日本(にほん)のこれまでのいつの歴史(れきし)にもその例(れい)がないほど激(はげ)しいものです。日本(にほん)は今(いま)、非常(ひじょう)な困難(こんなん)と[21]、民主的(みんしゅてき)な平和(へいわ)の国(くに)として世界(せかい)の独立国(どくりつこく)として登場(とうじょう)するための努力(どりょく)をはじめております。これからの私(わたし)たち日本人(にほんじん)は、世界(せかい)に恥(は)ずかしくない市民(しみん)としてどういう風(ふう)でなければならないでしょうか。新(あたら)しい躾(しつけ)の問題(もんだい)も、こういう広(ひろ)い、雄大(ゆうだい)な立場(たちば)から考(かんが)えられなければならないであろうと思(おも)います。<br><br>躾(しつけ)という字(じ)をみますと、美(うつく)しく身(み)をもつことと思(おも)えます。美(うつく)しく身(み)を持(じ)した生活態度(せいかつたいど)というのは、どういうことを指(さ)していっているのでしょう。昔(むかし)から躾(しつけ)というと、とかく[22]、折(お)り目(め)正(ただ)しいキチンとしたことを、躾(しつけ)がよいと[23]。しかし、今日(こんにち)の生活(せいかつ)は忙(いそが)しく、変化(へんか)が激(はげ)しく、混(こ)んだ電車(でんしゃ)一(ひと)つに乗(の)るにしても、実際(じっさい)には昔風(むかしふう)の躾(しつけ)とちがった事情(じじょう)がおこって来(き)ています。しとやかに男(おとこ)の人(ひと)のうしろについて、つつましく乗物(のりもの)にのるのが昔(むかし)の若(わか)い女性(じょせい)の躾(しつけ)でした。しかし毎朝毎夕(まいあさまいゆう)、満員電車(まんいんでんしゃ)に押(お)しこまれ押(お)し出(だ)されて通勤(つうきん)する女性(じょせい)たちは、昔(むかし)の躾(しつけ)を守(まも)っていたら電車(でんしゃ)一(ひと)つにも乗(の)れません。生活(せいかつ)の現実(げんじつ)が、昔(むかし)の形式的(けいしきてき)な躾(しつけ)の型(かた)を押(お)し流(なが)してしまいました。<br><br>[24]、私(わたし)たちの心(こころ)には、やはり美(うつく)しく立派(りっぱ)な生(い)きかたをしたいと思(おも)う念願(ねんがん)は強(つよ)くあります。そうだとすれば、新(あたら)しい躾(しつけ)の根本(こんぽん)は、毎日(まいにち)の荒(あら)っぽい生活(せいかつ)に[25]根深(ねぶか)い根拠(こんきょ)をもつものでなければならないということが分(わ)かります。",
    "passageTrans": "이 반년 사이에 우리의 생활에 일어난 변화는 일본의 지금까지 어느 역사에도 그 유례가 없을 만큼 격심한 것입니다. 일본은 지금 비상한 곤란과 [21: 싸우면서], 민주적인 평화의 나라로서 세계의 독립국으로 등장하기 위한 노력을 시작하고 있습니다. 앞으로 우리 일본인은 세계에 부끄럽지 않은 시민으로서 어떤 모습이어야 할까요. 새로운 예절(몸가짐)의 문제도 이러한 넓고 웅대한 입장에서 생각되지 않으면 안 될 것이라고 생각합니다.\n\n예절(躾)이라는 글자를 보면 '아름답게 몸을 가짐'이라고 여겨집니다. 아름답게 몸가짐을 지닌 생활 태도라는 것은 어떠한 것을 가리켜 말하는 것일까요. 예로부터 예절이라고 하면 으레 [22: 행동거지·예의범절], 빈틈없이 깍듯한 것을 예절이 바르다고 [23: 일컬어져 왔습니다]. 그러나 오늘날의 생활은 분주하고 변화가 극심하여 붐비는 전철 하나를 타더라도 실제로는 옛날식 예절과 다른 사정이 일어나고 있습니다. 얌전하게 남자의 뒤를 따라 조신하게 탈것을 타는 것이 옛날 젊은 여성의 예절이었습니다. 그러나 매일 아침저녁 만원 전철에 밀려 들어가고 밀려 나오며 통근하는 여성들은 옛날의 예절을 지키고 있어서는 전철 하나도 탈 수 없습니다. 생활의 현실이 옛날의 형식적인 예절의 틀을 휩쓸어 가 버렸습니다.\n\n[24: 그렇지만], 우리의 마음에는 역시 아름답고 훌륭한 삶을 살고 싶다는 염원은 강하게 남아 있습니다. 그렇다고 한다면 새로운 예절의 근본은 매일의 거친 생활에 [25: 휩쓸려 버리지 않을 만큼의] 깊은 뿌리를 가진 근거를 지닌 것이어야 함을 알 수 있습니다.",
