    "passagePlain": "劇は崇高な芸術の一分野というよりは、むしろ娯楽という一段低い分野に属するものであり、喪中であるとか、あるいは謹慎しなければならないような状況では避けるべきものと考えられていた時代があった。しかし、演劇が持つ人間の喜怒哀楽を鋭く抉り出す力や、社会の矛盾を白日の下に晒す力は、単なる一時的な気晴らしや娯楽の範疇をはるかに超えている。演劇を通じて人間存在の深淵に触れるとき、それは他のいかなる純粋芸術にも劣らない高潔な精神的営為となるのである。",
    "passageRuby": "劇(げき)は崇高(すうこう)な芸術(げいじゅつ)の一分野(いちぶんや)というよりは、むしろ娯楽(ごらく)という一段(いちだん)低(ひく)い分野(ぶんや)に属(ぞく)するものであり、喪中(もちゅう)であるとか、あるいは謹慎(きんしん)しなければならないような状況(じょうきょう)では避(さ)けるべきものと考(かんが)えられていた時代(じだい)があった。しかし、演劇(えんげき)が持(も)つ人間(にんげん)の喜怒哀楽(きどあいらく)を鋭(설)く抉(えぐ)り出(だ)す力(ちから)や、社会(しゃかい)の矛盾(むじゅん)を白日(はくじつ)の下(もと)に晒(さら)す力(ちから)は、単(たん)なる一時的(いちじてき)な気晴(きば)らしや娯楽(ごらく)の範疇(はんちゅう)をはるかに超(こ)えている。演劇(えんげき)を通(つう)じて人間存在(にんげんそんざい)の深淵(しんえん)に触(ふ)れるとき、それは他(ほか)のいかなる純粋芸術(じゅんすいげいじゅつ)にも劣(おと)らない高潔(こうけつ)な精神的営為(せいしんてきえいい)となるのである。",
    "passageTrans": "연극은 숭고한 예술의 한 분야라기보다는 오히려 오락이라는 한 단계 낮은 분야에 속하는 것이며, 상중이라든가 혹은 근신해야 하는 상황에서는 피해야 할 것으로 여겨지던 시대가 있었다. 그러나 연극이 가진 인간의 희로애락을 날카롭게 파헤치는 힘이나 사회의 모순을 대낮 아래 드러내는 힘은 단순한 일시적인 기분 전환이나 오락의 범주를 훨씬 뛰어넘고 있다. 연극을 통해 인간 존재의 심연에 닿을 때, 그것은 다른 어떠한 순수 예술에도 뒤지지 않는 고결한 정신적 행위가 되는 것이다.",
