    "title": "영상과 언어의 본질 (映像と言語)",
    "source": "시나공 JLPT N2 문제분석과 완벽대비법 중문이해 예제 (p.13~14)",
    "wordCount": 580,
    "estimatedMinutes": 6,
    "passagePlain": "今日、「映像」という言葉は極めて日常的に、かつ頻繁に使用されている。しかし、「映像とは何か」という問いに、①必ずしも正確には答えられないのが実情である。かつて映像という言葉は、写真や映画といった特定のメディアを指す限定的な意味で使われていた。しかし現代では、テレビやインターネット、デジタル動画に至るまで、視覚に訴えるあらゆる情報が「映像」と呼ばれ、その概念は極めて広範囲で曖昧なものになっている。\n\n映像の状況を考える上で重要なのは、②映像が言葉の意味を代替したり、時には言葉の領域を侵食したりしている点である。大量の映像情報が氾濫する中で、私たちは深く思考し言語化する前に、直感的なイメージだけで物事を判断しがちである。そのため、私たちは③映像の持つ意味や影響力を、より基本的で根本的な視点から捉え直す必要がある。",
    "passageRuby": "今日(こんにち)、「映像(えいぞう)」という言葉(ことば)は極(きわ)めて日常的(にちじょうてき)に、かつ頻繁(ひんぱん)に使用(しよう)されている。しかし、「映像(えいぞう)とは何(なに)か」という問(と)いに、①<u>必(かなら)ずしも正確(せいかく)には答(こた)えられない</u>のが実情(じつじょう)である。かつて映像(えいぞう)という言葉(ことば)は、写真(しゃしん)や映画(えいが)といった特定(とくてい)のメディア(めでぃあ)を指(さ)す限定的(げんていてき)な意味(いみ)で使(つか)われていた。しかし現代(げんだい)では、テレビ(てれび)やインターネット(いんたーねっと)、デジタル動画(どうが)に至(いた)るまで、視覚(しかく)に訴(うった)えるあらゆる情報(じょうほう)が「映像(えいぞう)」と呼(よ)ばれ、その概念(がいねん)は極(きわ)めて広範囲(こうはんい)で曖昧(あいまい)なものになっている。<br><br>映像(えいぞう)の状況(じょうきょう)を考(かんが)える上(うえ)で重要(じゅうよう)なのは、②<u>映像(えいぞう)が言葉(ことば)の意味(いみ)を代替(だいたい)したり、時(とき)には言葉(ことば)の領域(りょういき)を侵食(しんしょく)したりしている点(てん)</u>である。大量(たいりょう)の映像情報(えいぞうじょうほう)が氾濫(はんらん)する中(なか)で、私(わたし)たちは深(ふか)く思考(しこう)し言語化(げんごか)する前(まえ)に、直感的(ちょっかんてき)なイメージ(いめーじ)だけで物事(ものごと)を判断(はんだん)しがちである。そのため、私(わたし)たちは③<u>映像(えいぞう)の持(も)つ意味(いみ)や影響力(えいきょうりょく)を、より基本的(きほんてき)で根本的(こんぽんてき)な視点(してん)から捉(とら)え直(なお)す必要(ひつよう)がある</u>。",
    "passageTrans": "오늘날 '영상'이라는 말은 지극히 일상적으로 또한 빈번하게 사용되고 있다. 그러나 '영상이란 무엇인가'라는 질문에 ①반드시 정확하게는 대답할 수 없는 것이 실정이다. 과거에 영상이라는 말은 사진이나 영화와 같은 특정한 미디어를 가리키는 한정적인 의미로 사용되었다. 그러나 현대에는 텔레비전이나 인터넷, 디지털 동영상에 이르기까지 시각에 호소하는 모든 정보가 '영상'이라 불리며 그 개념은 지극히 광범위하고 애매한 것이 되었다.\n\n영상의 상황을 생각하는 데 중요한 것은 ②영상이 말의 의미를 대체하거나 때로는 말의 영역을 침식하고 있다는 점이다. 대량의 영상 정보가 범람하는 속에서 우리는 깊이 사고하고 언어화하기 전에 직관적인 이미지만으로 사물을 판단하기 쉽다. 그렇기 때문에 우리는 ③영상이 가진 의미와 영향력을 보다 기본적이고 근본적인 관점에서 다시 포착할 필요가 있다.",
