    "typeCode": "short",
    "typeName": "단문 독해",
    "title": "현대 사회에서의 '창조적 고독'의 가치",
    "wordCount": 310,
    "estimatedMinutes": 3,
    "passagePlain": "現代社会では、「孤独」はしばしば否定的な状態として捉えられがちである。SNSを通じて常に誰かと繋がっていることが求められ、一人でいることは寂しさや社会的な孤立の象徴と見なされることが多い。しかし、本来の孤独とは他者から強制的に断絶されることではなく、自己と深く対話するための不可欠な時間である。溢れる情報や他者の評価から意図的に距離を置き、自分自身の内面と向き合う「創造的孤独」を持つことによってのみ、人は独自の思考や自律した精神を育むことができるのではないだろうか。孤独を恐れて常に他者との繋がりを求め続けることは、かえって自己を見失う危険を孕んでいる。",
    "passageRuby": "現代社会(げんだいしゃかい)では、「孤独(こどく)」はしばしば否定的(ひていてき)な状態(じょうたい)として捉(とら)えられがちである。SNSを通(つう)じて常(つね)に誰(だれ)かと繋(つな)がっていることが求(もと)められ、一人(ひとり)でいることは寂(さび)しさや社会的(しゃかいてき)な孤立(こりつ)の象徴(しょうちょう)と見(み)なされることが多(おお)い。しかし、本来(ほんらい)の孤独(こどく)とは他者(たしゃ)から強制的(きょうせいてき)に断絶(だんぜつ)されることではなく、<u>自己(じこ)と深(ふか)く対話(たいわ)するための不可欠(ふかけつ)な時間(じかん)</u>である。溢(あふ)れる情報(じょうほう)や他者(たしゃ)の評価(ひょうか)から意図的(いとてき)に距離(きょり)を置(お)き、自分自身(じぶんじしん)の内面(ないめん)と向(む)き合(あ)う「創造的孤独(そうぞうてきこどく)」を持(も)つことによってのみ、人(ひと)は独自(どくじ)の思考(しこう)や自律(じりつ)した精神(せいしん)を育(はぐく)むことができるのではないだろうか。孤独(こどく)を恐(おそ)れて常(つね)に他者(たしゃ)との繋(つな)がりを求(もと)め続(つづ)けることは、かえって自己(じこ)を見失(みうしな)う危険(きけん)を孕(はら)んでいる。",
    "passageTrans": "현대 사회에서는 '고독'이 종종 부정적인 상태로 여겨지기 십상이다. SNS를 통해 항상 누군가와 연결되어 있는 것이 요구되고, 혼자 있는 것은 외로움이나 사회적 고립의 상징으로 간주되는 경우가 많다. 그러나 본래의 고독이란 타인으로부터 강제적으로 단절되는 것이 아니라, 자기 자신과 깊이 대화하기 위한 필수적인 시간이다. 넘쳐나는 정보나 타인의 평가로부터 의도적으로 거리를 두고, 자기 자신의 내면과 마주하는 '창조적 고독'을 가짐으로써만, 인간은 독자적인 사고와 자율적인 정신을 기를 수 있는 것이 아닐까. 고독을 두려워하여 끊임없이 타인과의 연결만을 추구하는 것은, 오히려 자기 자신을 잃어버릴 위험을 내포하고 있다.",
