    "passagePlain": "仕事の依頼を断る際、単に「時間がありません」や「対応できません」とだけ伝えるのは得策ではない。相手は拒絶されたと感じ、今後の関係に悪影響を及ぼしかねないからである。円滑な関係を保つためには、まず依頼してくれたことへの感謝を示した上で、引き受けられない客観的な理由を簡潔に説明することが大切だ。さらに、「来週以降であれば可能です」や「この部分だけであればお手伝いできます」といった代替案を添えることで、相手に対する誠意が伝わり、信頼関係を損なわずに済むのである。",
    "passageRuby": "仕事(しごと)の依頼(いらい)を断(ことわ)る際(さい)、単(たん)に「時間(じかん)がありません」や「対応(たいおう)できません」とだけ伝(つた)えるのは得策(とくさく)ではない。相手(あいて)は拒絶(きょぜつ)されたと感(かん)じ、今後(こんご)の関係(かんけい)に悪影響(あくえいきょう)を及(およ)ぼしかねないからである。円滑(えんかつ)な関係(かんけい)を保(たも)つためには、まず依頼(いらい)してくれたことへの感謝(かんしゃ)を示(しめ)した上(うえ)で、引(ひ)き受(う)けられない客観的(きゃっかんてき)な理由(りゆう)を簡潔(かんけつ)に説明(せつめい)することが大切(たいせつ)だ。さらに、「来週以降(らいしゅういこう)であれば可能(かのう)です」や「この部分(ぶぶん)だけであればお手伝(てづだ)いできます」といった<u>代替案(だいたいあん)を添(そ)える</u>ことで、相手(あいて)に対(たい)する誠意(せいい)が伝(つた)わり、信頼関係(しんらいかんけい)を損(そこ)なわずに済(す)むのである。",
    "passageTrans": "업무 의뢰를 거절할 때, 단순히 '시간이 없습니다'라거나 '대응할 수 없습니다'라고만 전달하는 것은 좋은 방책이 아니다. 상대방은 거절당했다고 느껴 향후 관계에 악영향을 미칠 수도 있기 때문이다. 원활한 관계를 유지하기 위해서는 먼저 의뢰해 준 것에 대한 감사를 표한 뒤, 맡을 수 없는 객관적인 이유를 간결하게 설명하는 것이 중요하다. 나아가 '다음 주 이후라면 가능합니다'나 '이 부분만이라면 도와드릴 수 있습니다'와 같은 대체안을 덧붙임으로써 상대에 대한 성의가 전달되어 신뢰 관계를 해치지 않고 넘어갈 수 있는 것이다.",
